function resolvePlayerCollisions(dt){if(state!=='playing')return;for(let i=0;i<players.length;i++)for(let j=i+1;j<players.length;j++){const a=players[i],b=players[j];if(a.fallen||b.fallen||a.finished||b.finished)continue;let nx=b.g.position.x-a.g.position.x,nz=b.g.position.z-a.g.position.z,dist=Math.hypot(nx,nz);if(dist>=1.02)continue;if(dist<.001){nx=Math.random()-.5;nz=Math.random()-.5;dist=Math.hypot(nx,nz)}nx/=dist;nz/=dist;const overlap=1.02-dist,hitA=Math.max(0,a.motionX*nx+a.motionZ*nz),hitB=Math.max(0,-b.motionX*nx-b.motionZ*nz),base=overlap*.52+.018;a.g.position.x-=nx*(base+hitB*dt*.22);a.g.position.z-=nz*(base+hitB*dt*.22);b.g.position.x+=nx*(base+hitA*dt*.22);b.g.position.z+=nz*(base+hitA*dt*.22)}}
const animatedTrees=[],clouds=[],foam=[];
function voxelTree(i){const g=new THREE.Group(),trunk=box(.55,3,.55,i%3?0x6d4928:0x8b6530),crown=new THREE.Group(),leafColors=[0x2d6f2c,0x3f8335,0x4f913c,0x285f2a];trunk.position.y=1.05;g.add(trunk,crown);for(const [x,y,z,s] of [[0,2.7,0,1.7],[-.85,2.55,0,1.05],[.85,2.6,.15,1.15],[0,3.5,0,1.15]]){const leaf=box(s,s,s,leafColors[i%leafColors.length]);leaf.position.set(x,y,z);crown.add(leaf)}g.userData.phase=Math.random()*6.28;animatedTrees.push({g,crown});return g}
for(let i=0;i<42;i++){const g=voxelTree(i);g.position.set((i%2?1:-1)*(14+Math.random()*22),0,-52+Math.random()*104);g.scale.setScalar(.65+Math.random()*.65);scene.add(g)}
function voxelIsland(x,z,scale,color){const g=new THREE.Group();for(let layer=0;layer<3;layer++){const size=(5-layer)*scale,b=box(size,1.1*scale,size*.75,layer===2?color:layer===1?0x8c7148:0x53616d);b.position.y=-.15+layer*.7*scale;g.add(b)}g.position.set(x,-.65,z);scene.add(g)}
for(let i=0;i<10;i++)voxelIsland((i%2?1:-1)*(24+Math.random()*22),-60+Math.random()*120,.7+Math.random()*.8,i%3?0x76c76c:0xd9c56f);
for(let i=0;i<9;i++){const g=new THREE.Group();for(const [x,y,s] of [[0,0,2.6],[-2,0,1.7],[2,0,1.9],[.3,.8,1.5]]){const b=box(s,.8,s*.65,0xf4fbff);b.position.set(x,y,0);g.add(b)}g.position.set(-48+Math.random()*96,11+Math.random()*8,-70+Math.random()*140);g.userData.speed=.45+Math.random()*.45;g.userData.phase=Math.random()*6.28;clouds.push(g);scene.add(g)}
const foamGeo=new THREE.PlaneGeometry(1.8,.28);for(let i=0;i<40;i++){const f=new THREE.Mesh(foamGeo,new THREE.MeshBasicMaterial({color:0xc7f8ff,transparent:true,opacity:.28+Math.random()*.28,depthWrite:false}));f.rotation.x=-Math.PI/2;f.rotation.z=(Math.random()-.5)*.35;f.position.set(-44+Math.random()*88,-.57,-68+Math.random()*136);f.scale.x=.7+Math.random()*2.5;f.userData.speed=.12+Math.random()*.2;f.userData.phase=Math.random()*6.28;foam.push(f);scene.add(f)}
const clock=new THREE.Clock,camTarget=new THREE.Vector3;function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.04),t=clock.elapsedTime;waterTex.offset.x=(t*.018)%1;waterTex.offset.y=(t*.011)%1;water.position.y=-.65+Math.sin(t*1.1)*.045;netherPortal.material.opacity=.62+Math.sin(t*2.4)*.12;netherPortal.scale.x=1+Math.sin(t*1.7)*.018;animatedTrees.forEach((o,i)=>{o.crown.rotation.z=Math.sin(t*.9+o.g.userData.phase)*.035;o.crown.position.y=Math.sin(t*1.15+o.g.userData.phase)*.045});clouds.forEach(c=>{c.position.x+=c.userData.speed*dt;if(c.position.x>58)c.position.x=-58;c.position.y+=Math.sin(t*.35+c.userData.phase)*.002});foam.forEach(f=>{f.position.x+=f.userData.speed*dt;if(f.position.x>49)f.position.x=-49;f.position.y=-.57+Math.sin(t*1.4+f.userData.phase)*.035});if(state==='countdown'){countTick+=dt;if(countTick>=1){countTick=0;count--;if(count<=0){countEl.textContent='START!';sfx('start');setTimeout(()=>countEl.textContent='',650);startRound()}else{countEl.textContent=count;sfx('count')}}}if(state==='playing'){timeLeft-=dt;timerEl.textContent=String(Math.max(0,Math.ceil(timeLeft)));timerEl.classList.toggle('urgent',timeLeft<2);if(timeLeft<=0)resolveRound()}if(state==='resolve'){resolveTime-=dt;if(resolveTime<=0)newLap()}tiles.forEach((tile,i)=>{tile.group.position.y=lerp(tile.group.position.y,tile.targetY,Math.min(1,dt*3.7));if(tile.alive)tile.group.position.y+=Math.sin(t*1.5+i*.42)*.0015});players.forEach((p,i)=>updatePlayer(p,dt,i));resolvePlayerCollisions(dt);const back=innerWidth<700?9.6:11.2,height=innerWidth<700?7.7:8.5;camTarget.set(hero.g.position.x*.22,height,hero.g.position.z+back);camera.position.lerp(camTarget,1-Math.pow(.001,dt));camera.lookAt(hero.g.position.x*.08,.42,hero.g.position.z-4.4);const active=[...players].sort((a,b)=>a.g.position.z-b.g.position.z);document.querySelector('#place').textContent=`${active.indexOf(hero)+1}/5`;document.querySelector('#progress').textContent=`${Math.round(clamp((39.4-hero.g.position.z)/77.5,0,1)*100)}%`;endWorld.update(dt);renderer.render(scene,camera)}const endWorld=createEndWorld(THREE,scene,{center:()=>hero.g.position});camera.position.set(0,8.5,50.6);frame();addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))});


</script><script src="/assets/visitor-counter.js" data-root="/"></script></body></html>
